def solve(grid):
    """
    My best guess at the rule:
    - Cells that can be reached from TOP edge via orthogonal neighbors (excluding background) → become 3
    - Special corner handling for bottom-left
    """
    rows, cols = len(grid), len(grid[0])

    # Find background color
    color_counts = {}
    for r in range(rows):
        for c in range(cols):
            v = grid[r][c]
            color_counts[v] = color_counts.get(v, 0) + 1

    background = max(color_counts.keys(), key=lambda x: color_counts[x])
    secondary = 3 if background == 6 else 3  # Based on demo, secondary is 3
    tertiary = 1

    # Flood from TOP edge through non-background cells
    visited = set()
    queue = [(r,c) for r in range(rows) for c in range(cols) 
             if r == 0 and grid[0][c] != background]

    directions = [(0,1),(0,-1),(1,0),(-1,0)]
    while queue:
        r,c = queue.pop(0)
        if (r,c) not in visited:
            visited.add((r,c))
            for dr,dc in directions:
                nr, nc = r+dr, c+dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if grid[nr][nc] != background and (nr,nc) not in visited:
                        queue.append((nr,nc))

    # Create output
    output = [[grid[r][c] for c in range(cols)] for r in range(rows)]
    for r in range(rows):
        for c in range(cols):
            if (r,c) in visited:
                output[r][c] = secondary

    return output

