def solve_inverted(demo_in):
    """Flood from background cells OUT through non-background"""
    rows, cols = len(demo_in), len(demo_in[0])

    # Find background color
    color_counts = {}
    for r in range(rows):
        for c in range(cols):
            v = demo_in[r][c]
            color_counts[v] = color_counts.get(v, 0) + 1

    background = max(color_counts.keys(), key=lambda x: color_counts[x])

    visited = set()
    queue = deque()

    # Start from ALL background cells
    for r in range(rows):
        for c in range(cols):
            if demo_in[r][c] == background:
                visited.add((r,c))
                queue.append((r,c))

    directions = [(0,1),(0,-1),(1,0),(-1,0)]
    while queue:
        r,c = queue.popleft()
        for dr,dc in directions:
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if demo_in[nr][nc] != background and (nr,nc) not in visited:
                    visited.add((nr,nc))
                    queue.append((nr,nc))

    # Output: visited = secondary, unvisited = primary
    secondary = 3
    output = [[demo_in[r][c] for c in range(cols)] for r in range(rows)]
    for r in range(rows):
        for c in range(cols):
            if (r,c) in visited:
                output[r][c] = secondary

    return output, background

