def solve_by_neighbor_count(demo_in, min_primary_neighbors):
    """Primary cells with >= min_primary_neighbors become secondary"""
    rows, cols = len(demo_in), len(demo_in[0])

    color_counts = {}
    for r in range(rows):
        for c in range(cols):
            v = demo_in[r][c]
            color_counts[v] = color_counts.get(v, 0) + 1

    background = max(color_counts.keys(), key=lambda x: color_counts[x])

    def count_primary_neighbors(r, c):
        count = 0
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if demo_in[nr][nc] == background:
                    count += 1
        return count

    output = [[demo_in[r][c] for c in range(cols)] for r in range(rows)]
    for r in range(rows):
        for c in range(cols):
            if demo_in[r][c] == background:
                pcount = count_primary_neighbors(r,c)
                if pcount >= min_primary_neighbors:
                    output[r][c] = 3

    return output

