def solve_by_distance(demo_in, threshold):
    """Background cells within 'threshold' Manhattan distance of a non-bg cell become secondary"""
    rows, cols = len(demo_in), len(demo_in[0])

    color_counts = {}
    for r in range(rows):
        for c in range(cols):
            v = demo_in[r][c]
            color_counts[v] = color_counts.get(v, 0) + 1

    background = max(color_counts.keys(), key=lambda x: color_counts[x])

    def dist_to_non_bg(r, c):
        min_d = float('inf')
        for rr in range(rows):
            for cc in range(cols):
                if demo_in[rr][cc] != background:
                    d = abs(r-rr) + abs(c-cc)
                    min_d = min(min_d, d)
        return min_d

    output = [[demo_in[r][c] for c in range(cols)] for r in range(rows)]
    for r in range(rows):
        for c in range(cols):
            if demo_in[r][c] == background:
                d = dist_to_non_bg(r,c)
                if d <= threshold:
                    output[r][c] = 3

    return output

